const still = matchMedia("(prefers-reduced-motion: reduce)");
const RUNS = [{"btn":"Read the stem cells","read":"148,453 tags","done":"Over 32,000 transcripts, more than half unknown. Tap to differentiate the cells."},{"btn":"Differentiate","read":"532 up · 140 down","done":"532 genes higher and 140 lower in stem cells than in their derivatives. Tap to read again."}];
