      + solidSvg(cylinder(x, y, C.PIPE_R + 1.6, z0 + h - 3, 3, P, 32, 0.3), { tone: "mid", crease: "lo" })
      + '<path class="hesc-genomics-2-mouth" d="' + pathOf([iso([...xy(C.PU[i] - 3.5, C.PIPE_V + C.PIPE_R * 0.98), z0 + 6], P), iso([...xy(C.PU[i] + 3.5, C.PIPE_V + C.PIPE_R * 0.98), z0 + 6], P), iso([...xy(C.PU[i] + 3.5, C.PIPE_V + C.PIPE_R * 0.98), z0 + 10], P), iso([...xy(C.PU[i] - 3.5, C.PIPE_V + C.PIPE_R * 0.98), z0 + 10], P)], true) + '"/>';
